def tob(s, enc=b'utf8'):
    if isinstance(s, unicode):
        return s.encode(enc)
    return bytes(s)


def touni(s, enc=b'utf8', err=b'strict'):
    if isinstance(s, bytes):
        return s.decode(enc, err)
    return unicode(s)


tonat = touni if py3k else tob
