def _re_flatten(p):
    if b'(' not in p:
        return p
    return re.sub(b'(\\\\*)(\\(\\?P<[^>]+>|\\((?!\\?))', (lambda m: m.group(0) if len(m.group(1)) % 2 else m.group(1) + b'(?:'), p)


class Router(object):
    default_pattern = b'[^/]+'
    default_filter = b're'
    _MAX_GROUPS_PER_PATTERN = 99

    def __init__(self, strict=False):
        self.rules = []
        self._groups = {}
        self.builder = {}
        self.static = {}
        self.dyna_routes = {}
        self.dyna_regexes = {}
        self.strict_order = strict
        self.filters = {b're': (lambda conf: (
                 _re_flatten(conf or self.default_pattern), None, None)), 
           b'int': (lambda conf: (
                  b'-?\\d+', int, (lambda x: str(int(x))))), 
           b'float': (lambda conf: (
                    b'-?[\\d.]+', float, (lambda x: str(float(x))))), 
           b'path': (lambda conf: (b'.+?', None, None))}
        return

    def add_filter(self, name, func):
        self.filters[name] = func
        return

    rule_syntax = re.compile(b'(\\\\*)(?:(?::([a-zA-Z_][a-zA-Z_0-9]*)?()(?:#(.*?)#)?)|(?:<([a-zA-Z_][a-zA-Z_0-9]*)?(?::([a-zA-Z_]*)(?::((?:\\\\.|[^\\\\>]+)+)?)?)?>))')

    def _itertokens(self, rule):
        offset, prefix = (0, b'')
        for match in self.rule_syntax.finditer(rule):
            prefix += rule[offset:match.start()]
            g = match.groups()
            if len(g[0]) % 2:
                prefix += match.group(0)[len(g[0]):]
                offset = match.end()
                continue
            if prefix:
                yield (
                 prefix, None, None)
            name, filtr, conf = g[4:7] if g[2] is None else g[1:4]
            yield (name, filtr or b'default', conf or None)
            offset, prefix = match.end(), b''

        if offset <= len(rule) or prefix:
            yield (
             prefix + rule[offset:], None, None)
        return

    def add(self, rule, method, target, name=None):
        global DEBUG
        anons = 0
        keys = []
        pattern = b''
        filters = []
        builder = []
        is_static = True
        for key, mode, conf in self._itertokens(rule):
            if mode:
                is_static = False
                if mode == b'default':
                    mode = self.default_filter
                mask, in_filter, out_filter = self.filters[mode](conf)
                if not key:
                    pattern += b'(?:%s)' % mask
                    key = b'anon%d' % anons
                    anons += 1
                else:
                    pattern += b'(?P<%s>%s)' % (key, mask)
                    keys.append(key)
                if in_filter:
                    filters.append((key, in_filter))
                builder.append((key, out_filter or str))
            elif key:
                pattern += re.escape(key)
                builder.append((None, key))

        self.builder[rule] = builder
        if name:
            self.builder[name] = builder
        if is_static and not self.strict_order:
            self.static.setdefault(method, {})
            self.static[method][self.build(rule)] = (target, None)
            return
        else:
            try:
                re_pattern = re.compile(b'^(%s)$' % pattern)
                re_match = re_pattern.match
            except re.error:
                raise RouteSyntaxError(b'Could not add Route: %s (%s)' % (rule, _e()))

            if filters:

                def getargs(path):
                    url_args = re_match(path).groupdict()
                    for name, wildcard_filter in filters:
                        try:
                            url_args[name] = wildcard_filter(url_args[name])
                        except ValueError:
                            raise HTTPError(400, b'Path has wrong format.')

                    return url_args

            elif re_pattern.groupindex:

                def getargs(path):
                    return re_match(path).groupdict()

            else:
                getargs = None
            flatpat = _re_flatten(pattern)
            whole_rule = (rule, flatpat, target, getargs)
            if (
             flatpat, method) in self._groups:
                if DEBUG:
                    msg = b'Route <%s %s> overwrites a previously defined route'
                    warnings.warn(msg % (method, rule), RuntimeWarning)
                self.dyna_routes[method][self._groups[flatpat, method]] = whole_rule
            else:
                self.dyna_routes.setdefault(method, []).append(whole_rule)
                self._groups[(flatpat, method)] = len(self.dyna_routes[method]) - 1
            self._compile(method)
            return

    def _compile(self, method):
        all_rules = self.dyna_routes[method]
        comborules = self.dyna_regexes[method] = []
        maxgroups = self._MAX_GROUPS_PER_PATTERN
        for x in range(0, len(all_rules), maxgroups):
            some = all_rules[x:x + maxgroups]
            combined = (flatpat for _, flatpat, _, _ in some)
            combined = (b'|').join(b'(^%s$)' % flatpat for flatpat in combined)
            combined = re.compile(combined).match
            rules = [(target, getargs) for _, _, target, getargs in some]
            comborules.append((combined, rules))

        return

    def build(self, _name, *anons, **query):
        builder = self.builder.get(_name)
        if not builder:
            raise RouteBuildError(b'No route with that name.', _name)
        try:
            for i, value in enumerate(anons):
                query[b'anon%d' % i] = value

            url = (b'').join([f(query.pop(n)) if n else f for n, f in builder])
            if not query:
                return url
            return url + b'?' + urlencode(query)
        except KeyError:
            raise RouteBuildError(b'Missing URL argument: %r' % _e().args[0])

        return

    def match(self, environ):
        verb = environ[b'REQUEST_METHOD'].upper()
        path = environ[b'PATH_INFO'] or b'/'
        target = None
        if verb == b'HEAD':
            methods = [
             b'PROXY', verb, b'GET', b'ANY']
        else:
            methods = [
             b'PROXY', verb, b'ANY']
        for method in methods:
            if method in self.static and path in self.static[method]:
                target, getargs = self.static[method][path]
                return (target, getargs(path) if getargs else {})
            if method in self.dyna_regexes:
                for combined, rules in self.dyna_regexes[method]:
                    match = combined(path)
                    if match:
                        target, getargs = rules[match.lastindex - 1]
                        return (target, getargs(path) if getargs else {})

        allowed = set([])
        nocheck = set(methods)
        for method in set(self.static) - nocheck:
            if path in self.static[method]:
                allowed.add(verb)

        for method in set(self.dyna_regexes) - allowed - nocheck:
            for combined, rules in self.dyna_regexes[method]:
                match = combined(path)
                if match:
                    allowed.add(method)

        if allowed:
            allow_header = (b',').join(sorted(allowed))
            raise HTTPError(405, b'Method not allowed.', Allow=allow_header)
        raise HTTPError(404, b'Not found: ' + repr(path))
        return


class Route(object):

    def __init__(self, app, rule, method, callback, name=None, plugins=None, skiplist=None, **config):
        self.app = app
        self.rule = rule
        self.method = method
        self.callback = callback
        self.name = name or None
        self.plugins = plugins or []
        self.skiplist = skiplist or []
        self.config = ConfigDict().load_dict(config, make_namespaces=True)
        return

    def __call__(self, *a, **ka):
        depr(b'Some APIs changed to return Route() instances instead of callables. Make sure to use the Route.call method and not to call Route instances directly.')
        return self.call(*a, **ka)

    @cached_property
    def call(self):
        return self._make_callback()

    def reset(self):
        self.__dict__.pop(b'call', None)
        return

    def prepare(self):
        self.call
        return

    @property
    def _context(self):
        depr(b'Switch to Plugin API v2 and access the Route object directly.')
        return dict(rule=self.rule, method=self.method, callback=self.callback, name=self.name, app=self.app, config=self.config, apply=self.plugins, skip=self.skiplist)

    def all_plugins(self):
        unique = set()
        for p in reversed(self.app.plugins + self.plugins):
            if True in self.skiplist:
                break
            name = getattr(p, b'name', False)
            if name and (name in self.skiplist or name in unique):
                continue
            if p in self.skiplist or type(p) in self.skiplist:
                continue
            if name:
                unique.add(name)
            yield p

        return

    def _make_callback(self):
        callback = self.callback
        for plugin in self.all_plugins():
            try:
                if hasattr(plugin, b'apply'):
                    api = getattr(plugin, b'api', 1)
                    context = self if api > 1 else self._context
                    callback = plugin.apply(callback, context)
                else:
                    callback = plugin(callback)
            except RouteReset:
                return self._make_callback()

            if callback is not self.callback:
                update_wrapper(callback, self.callback)

        return callback

    def get_undecorated_callback(self):
        func = self.callback
        func = getattr(func, b'__func__' if py3k else b'im_func', func)
        closure_attr = b'__closure__' if py3k else b'func_closure'
        while hasattr(func, closure_attr) and getattr(func, closure_attr):
            func = getattr(func, closure_attr)[0].cell_contents

        return func

    def get_callback_args(self):
        return getargspec(self.get_undecorated_callback())[0]

    def get_config(self, key, default=None):
        for conf in (self.config, self.app.conifg):
            if key in conf:
                return conf[key]

        return default

    def __repr__(self):
        cb = self.get_undecorated_callback()
        return b'<%s %r %r>' % (self.method, self.rule, cb)


class Bottle(object):

    def __init__(self, catchall=True, autojson=True):
        self.config = ConfigDict()
        self.config._on_change = functools.partial(self.trigger_hook, b'config')
        self.config.meta_set(b'autojson', b'validate', bool)
        self.config.meta_set(b'catchall', b'validate', bool)
        self.config[b'catchall'] = catchall
        self.config[b'autojson'] = autojson
        self.resources = ResourceManager()
        self.routes = []
        self.router = Router()
        self.error_handler = {}
        self.plugins = []
        if self.config[b'autojson']:
            self.install(JSONPlugin())
        self.install(TemplatePlugin())
        return

    catchall = DictProperty(b'config', b'catchall')
    __hook_names = (b'before_request', b'after_request', b'app_reset', b'config')
    __hook_reversed = b'after_request'

    @cached_property
    def _hooks(self):
        return dict((name, []) for name in self.__hook_names)

    def add_hook(self, name, func):
        if name in self.__hook_reversed:
            self._hooks[name].insert(0, func)
        else:
            self._hooks[name].append(func)
        return

    def remove_hook(self, name, func):
        if name in self._hooks and func in self._hooks[name]:
            self._hooks[name].remove(func)
            return True
        return

    def trigger_hook(self, _Bottle__name, *args, **kwargs):
        return [hook(*args, **kwargs) for hook in self._hooks[__name][:]]

    def hook(self, name):

        def decorator(func):
            self.add_hook(name, func)
            return func

        return decorator

    def mount(self, prefix, app, **options):
        if isinstance(app, basestring):
            depr(b'Parameter order of Bottle.mount() changed.', True)
        segments = [p for p in prefix.split(b'/') if p]
        if not segments:
            raise ValueError(b'Empty path prefix.')
        path_depth = len(segments)

        def mountpoint_wrapper():
            try:
                request.path_shift(path_depth)
                rs = HTTPResponse([])

                def start_response(status, headerlist, exc_info=None):
                    if exc_info:
                        try:
                            _raise(*exc_info)
                        finally:
                            exc_info = None

                    rs.status = status
                    for name, value in headerlist:
                        rs.add_header(name, value)

                    return rs.body.append

                body = app(request.environ, start_response)
                if body and rs.body:
                    body = itertools.chain(rs.body, body)
                rs.body = body or rs.body
                return rs
            finally:
                request.path_shift(-path_depth)

            return

        options.setdefault(b'skip', True)
        options.setdefault(b'method', b'PROXY')
        options.setdefault(b'mountpoint', {b'prefix': prefix, b'target': app})
        options[b'callback'] = mountpoint_wrapper
        self.route((b'/%s/<:re:.*>' % (b'/').join(segments)), **options)
        if not prefix.endswith(b'/'):
            self.route((b'/' + (b'/').join(segments)), **options)
        return

    def merge(self, routes):
        if isinstance(routes, Bottle):
            routes = routes.routes
        for route in routes:
            self.add_route(route)

        return

    def install(self, plugin):
        if hasattr(plugin, b'setup'):
            plugin.setup(self)
        if not callable(plugin) and not hasattr(plugin, b'apply'):
            raise TypeError(b'Plugins must be callable or implement .apply()')
        self.plugins.append(plugin)
        self.reset()
        return plugin

    def uninstall(self, plugin):
        removed, remove = [], plugin
        for i, plugin in list(enumerate(self.plugins))[::-1]:
            if remove is True or remove is plugin or remove is type(plugin) or getattr(plugin, b'name', True) == remove:
                removed.append(plugin)
                del self.plugins[i]
                if hasattr(plugin, b'close'):
                    plugin.close()

        if removed:
            self.reset()
        return removed

    def reset(self, route=None):
        if route is None:
            routes = self.routes
        elif isinstance(route, Route):
            routes = [route]
        else:
            routes = [
             self.routes[route]]
        for route in routes:
            route.reset()

        if DEBUG:
            for route in routes:
                route.prepare()

        self.trigger_hook(b'app_reset')
        return

    def close(self):
        for plugin in self.plugins:
            if hasattr(plugin, b'close'):
                plugin.close()

        self.stopped = True
        return

    def run(self, **kwargs):
        run(self, **kwargs)
        return

    def match(self, environ):
        return self.router.match(environ)

    def get_url(self, routename, **kargs):
        scriptname = request.environ.get(b'SCRIPT_NAME', b'').strip(b'/') + b'/'
        location = self.router.build(routename, **kargs).lstrip(b'/')
        return urljoin(urljoin(b'/', scriptname), location)

    def add_route(self, route):
        self.routes.append(route)
        self.router.add(route.rule, route.method, route, name=route.name)
        if DEBUG:
            route.prepare()
        return

    def route(self, path=None, method=b'GET', callback=None, name=None, apply=None, skip=None, **config):
        if callable(path):
            path, callback = None, path
        plugins = makelist(apply)
        skiplist = makelist(skip)

        def decorator(callback):
            if isinstance(callback, basestring):
                callback = load(callback)
            for rule in makelist(path) or yieldroutes(callback):
                for verb in makelist(method):
                    verb = verb.upper()
                    route = Route(self, rule, verb, callback, name=name, plugins=plugins, skiplist=skiplist, **config)
                    self.add_route(route)

            return callback

        if callback:
            return decorator(callback)
        else:
            return decorator

    def get(self, path=None, method=b'GET', **options):
        return self.route(path, method, **options)

    def post(self, path=None, method=b'POST', **options):
        return self.route(path, method, **options)

    def put(self, path=None, method=b'PUT', **options):
        return self.route(path, method, **options)

    def delete(self, path=None, method=b'DELETE', **options):
        return self.route(path, method, **options)

    def error(self, code=500):

        def wrapper(handler):
            self.error_handler[int(code)] = handler
            return handler

        return wrapper

    def default_error_handler(self, res):
        return tob(template(ERROR_PAGE_TEMPLATE, e=res))

    def _handle(self, environ):
        path = environ[b'bottle.raw_path'] = environ[b'PATH_INFO']
        if py3k:
            try:
                environ[b'PATH_INFO'] = path.encode(b'latin1').decode(b'utf8')
            except UnicodeError:
                return HTTPError(400, b'Invalid path string. Expected UTF-8')

        try:
            environ[b'bottle.app'] = self
            request.bind(environ)
            response.bind()
            try:
                self.trigger_hook(b'before_request')
                route, args = self.router.match(environ)
                environ[b'route.handle'] = route
                environ[b'bottle.route'] = route
                environ[b'route.url_args'] = args
                return route.call(**args)
            finally:
                self.trigger_hook(b'after_request')

        except HTTPResponse:
            return _e()
        except RouteReset:
            route.reset()
            return self._handle(environ)
        except (KeyboardInterrupt, SystemExit, MemoryError):
            raise
        except Exception:
            if not self.catchall:
                raise
            stacktrace = format_exc()
            environ[b'wsgi.errors'].write(stacktrace)
            return HTTPError(500, b'Internal Server Error', _e(), stacktrace)

        return

    def _cast(self, out, peek=None):
        if not out:
            if b'Content-Length' not in response:
                response[b'Content-Length'] = 0
            return []
        if isinstance(out, (tuple, list)) and isinstance(out[0], (bytes, unicode)):
            out = out[0][0:0].join(out)
        if isinstance(out, unicode):
            out = out.encode(response.charset)
        if isinstance(out, bytes):
            if b'Content-Length' not in response:
                response[b'Content-Length'] = len(out)
            return [out]
        if isinstance(out, HTTPError):
            out.apply(response)
            out = self.error_handler.get(out.status_code, self.default_error_handler)(out)
            return self._cast(out)
        if isinstance(out, HTTPResponse):
            out.apply(response)
            return self._cast(out.body)
        if hasattr(out, b'read'):
            if b'wsgi.file_wrapper' in request.environ:
                return request.environ[b'wsgi.file_wrapper'](out)
            if hasattr(out, b'close') or not hasattr(out, b'__iter__'):
                return WSGIFileWrapper(out)
        try:
            iout = iter(out)
            first = next(iout)
            while not first:
                first = next(iout)

        except StopIteration:
            return self._cast(b'')
        except HTTPResponse:
            first = _e()
        except (KeyboardInterrupt, SystemExit, MemoryError):
            raise
        except Exception:
            if not self.catchall:
                raise
            first = HTTPError(500, b'Unhandled exception', _e(), format_exc())

        if isinstance(first, HTTPResponse):
            return self._cast(first)
        if isinstance(first, bytes):
            new_iter = itertools.chain([first], iout)
        elif isinstance(first, unicode):
            encoder = lambda x: x.encode(response.charset)
            new_iter = imap(encoder, itertools.chain([first], iout))
        else:
            msg = b'Unsupported response type: %s' % type(first)
            return self._cast(HTTPError(500, msg))
        if hasattr(out, b'close'):
            new_iter = _closeiter(new_iter, out.close)
        return new_iter

    def wsgi(self, environ, start_response):
        try:
            out = self._cast(self._handle(environ))
            if response._status_code in (100, 101, 204, 304) or environ[b'REQUEST_METHOD'] == b'HEAD':
                if hasattr(out, b'close'):
                    out.close()
                out = []
            start_response(response._status_line, response.headerlist)
            return out
        except (KeyboardInterrupt, SystemExit, MemoryError):
            raise
        except Exception:
            if not self.catchall:
                raise
            err = b'<h1>Critical error while processing request: %s</h1>' % html_escape(environ.get(b'PATH_INFO', b'/'))
            if DEBUG:
                err += b'<h2>Error:</h2>\n<pre>\n%s\n</pre>\n<h2>Traceback:</h2>\n<pre>\n%s\n</pre>\n' % (
                 html_escape(repr(_e())), html_escape(format_exc()))
            environ[b'wsgi.errors'].write(err)
            headers = [(b'Content-Type', b'text/html; charset=UTF-8')]
            start_response(b'500 INTERNAL SERVER ERROR', headers, sys.exc_info())
            return [tob(err)]

        return

    def __call__(self, environ, start_response):
        return self.wsgi(environ, start_response)


class BaseRequest(object):
    __slots__ = b'environ'
    MEMFILE_MAX = 102400

    def __init__(self, environ=None):
        self.environ = {} if environ is None else environ
        self.environ[b'bottle.request'] = self
        return

    @DictProperty(b'environ', b'bottle.app', read_only=True)
    def app(self):
        raise RuntimeError(b'This request is not connected to an application.')
        return

    @DictProperty(b'environ', b'bottle.route', read_only=True)
    def route(self):
        raise RuntimeError(b'This request is not connected to a route.')
        return

    @DictProperty(b'environ', b'route.url_args', read_only=True)
    def url_args(self):
        raise RuntimeError(b'This request is not connected to a route.')
        return

    @property
    def path(self):
        return b'/' + self.environ.get(b'PATH_INFO', b'').lstrip(b'/')

    @property
    def method(self):
        return self.environ.get(b'REQUEST_METHOD', b'GET').upper()

    @DictProperty(b'environ', b'bottle.request.headers', read_only=True)
    def headers(self):
        return WSGIHeaderDict(self.environ)

    def get_header(self, name, default=None):
        return self.headers.get(name, default)

    @DictProperty(b'environ', b'bottle.request.cookies', read_only=True)
    def cookies(self):
        cookies = SimpleCookie(self.environ.get(b'HTTP_COOKIE', b'')).values()
        return FormsDict((c.key, c.value) for c in cookies)

    def get_cookie(self, key, default=None, secret=None):
        value = self.cookies.get(key)
        if secret and value:
            dec = cookie_decode(value, secret)
            if dec and dec[0] == key:
                return dec[1]
            return default
        return value or default

    @DictProperty(b'environ', b'bottle.request.query', read_only=True)
    def query(self):
        get = self.environ[b'bottle.get'] = FormsDict()
        pairs = _parse_qsl(self.environ.get(b'QUERY_STRING', b''))
        for key, value in pairs:
            get[key] = value

        return get

    @DictProperty(b'environ', b'bottle.request.forms', read_only=True)
    def forms(self):
        forms = FormsDict()
        for name, item in self.POST.allitems():
            if not isinstance(item, FileUpload):
                forms[name] = item

        return forms

    @DictProperty(b'environ', b'bottle.request.params', read_only=True)
    def params(self):
        params = FormsDict()
        for key, value in self.query.allitems():
            params[key] = value

        for key, value in self.forms.allitems():
            params[key] = value

        return params

    @DictProperty(b'environ', b'bottle.request.files', read_only=True)
    def files(self):
        files = FormsDict()
        for name, item in self.POST.allitems():
            if isinstance(item, FileUpload):
                files[name] = item

        return files

    @DictProperty(b'environ', b'bottle.request.json', read_only=True)
    def json(self):
        ctype = self.environ.get(b'CONTENT_TYPE', b'').lower().split(b';')[0]
        if ctype == b'application/json':
            b = self._get_body_string()
            if not b:
                return
            return json_loads(b)
        else:
            return

    def _iter_body(self, read, bufsize):
        maxread = max(0, self.content_length)
        while maxread:
            part = read(min(maxread, bufsize))
            if not part:
                break
            yield part
            maxread -= len(part)

        return

    def _iter_chunked(self, read, bufsize):
        err = HTTPError(400, b'Error while parsing chunked transfer body.')
        rn, sem, bs = tob(b'\r\n'), tob(b';'), tob(b'')
        while True:
            header = read(1)
            while header[-2:] != rn:
                c = read(1)
                header += c
                if not c:
                    raise err
                if len(header) > bufsize:
                    raise err

            size, _, _ = header.partition(sem)
            try:
                maxread = int(tonat(size.strip()), 16)
            except ValueError:
                raise err

            if maxread == 0:
                break
            buff = bs
            while maxread > 0:
                if not buff:
                    buff = read(min(maxread, bufsize))
                part, buff = buff[:maxread], buff[maxread:]
                if not part:
                    raise err
                yield part
                maxread -= len(part)

            if read(2) != rn:
                raise err

        return

    @DictProperty(b'environ', b'bottle.request.body', read_only=True)
    def _body(self):
        body_iter = self._iter_chunked if self.chunked else self._iter_body
        read_func = self.environ[b'wsgi.input'].read
        body, body_size, is_temp_file = BytesIO(), 0, False
        for part in body_iter(read_func, self.MEMFILE_MAX):
            body.write(part)
            body_size += len(part)
            if not is_temp_file and body_size > self.MEMFILE_MAX:
                body, tmp = TemporaryFile(mode=b'w+b'), body
                body.write(tmp.getvalue())
                del tmp
                is_temp_file = True

        self.environ[b'wsgi.input'] = body
        body.seek(0)
        return body

    def _get_body_string(self):
        clen = self.content_length
        if clen > self.MEMFILE_MAX:
            raise HTTPError(413, b'Request to large')
        if clen < 0:
            clen = self.MEMFILE_MAX + 1
        data = self.body.read(clen)
        if len(data) > self.MEMFILE_MAX:
            raise HTTPError(413, b'Request to large')
        return data

    @property
    def body(self):
        self._body.seek(0)
        return self._body

    @property
    def chunked(self):
        return b'chunked' in self.environ.get(b'HTTP_TRANSFER_ENCODING', b'').lower()

    GET = query

    @DictProperty(b'environ', b'bottle.request.post', read_only=True)
    def POST(self):
        post = FormsDict()
        if not self.content_type.startswith(b'multipart/'):
            pairs = _parse_qsl(tonat(self._get_body_string(), b'latin1'))
            for key, value in pairs:
                post[key] = value

            return post
        safe_env = {b'QUERY_STRING': b''}
        for key in (b'REQUEST_METHOD', b'CONTENT_TYPE', b'CONTENT_LENGTH'):
            if key in self.environ:
                safe_env[key] = self.environ[key]

        args = dict(fp=self.body, environ=safe_env, keep_blank_values=True)
        if py31:
            args[b'fp'] = NCTextIOWrapper(args[b'fp'], encoding=b'utf8', newline=b'\n')
        elif py3k:
            args[b'encoding'] = b'utf8'
        data = cgi.FieldStorage(**args)
        self[b'_cgi.FieldStorage'] = data
        data = data.list or []
        for item in data:
            if item.filename:
                post[item.name] = FileUpload(item.file, item.name, item.filename, item.headers)
            else:
                post[item.name] = item.value

        return post

    @property
    def url(self):
        return self.urlparts.geturl()

    @DictProperty(b'environ', b'bottle.request.urlparts', read_only=True)
    def urlparts(self):
        env = self.environ
        http = env.get(b'HTTP_X_FORWARDED_PROTO') or env.get(b'wsgi.url_scheme', b'http')
        host = env.get(b'HTTP_X_FORWARDED_HOST') or env.get(b'HTTP_HOST')
        if not host:
            host = env.get(b'SERVER_NAME', b'127.0.0.1')
            port = env.get(b'SERVER_PORT')
            if port and port != (b'80' if http == b'http' else b'443'):
                host += b':' + port
        path = urlquote(self.fullpath)
        return UrlSplitResult(http, host, path, env.get(b'QUERY_STRING'), b'')

    @property
    def fullpath(self):
        return urljoin(self.script_name, self.path.lstrip(b'/'))

    @property
    def query_string(self):
        return self.environ.get(b'QUERY_STRING', b'')

    @property
    def script_name(self):
        script_name = self.environ.get(b'SCRIPT_NAME', b'').strip(b'/')
        if script_name:
            return b'/' + script_name + b'/'
        return b'/'

    def path_shift(self, shift=1):
        script = self.environ.get(b'SCRIPT_NAME', b'/')
        self[b'SCRIPT_NAME'], self[b'PATH_INFO'] = path_shift(script, self.path, shift)
        return

    @property
    def content_length(self):
        return int(self.environ.get(b'CONTENT_LENGTH') or -1)

    @property
    def content_type(self):
        return self.environ.get(b'CONTENT_TYPE', b'').lower()

    @property
    def is_xhr(self):
        requested_with = self.environ.get(b'HTTP_X_REQUESTED_WITH', b'')
        return requested_with.lower() == b'xmlhttprequest'

    @property
    def is_ajax(self):
        return self.is_xhr

    @property
    def auth(self):
        basic = parse_auth(self.environ.get(b'HTTP_AUTHORIZATION', b''))
        if basic:
            return basic
        else:
            ruser = self.environ.get(b'REMOTE_USER')
            if ruser:
                return (ruser, None)
            return

    @property
    def remote_route(self):
        proxy = self.environ.get(b'HTTP_X_FORWARDED_FOR')
        if proxy:
            return [ip.strip() for ip in proxy.split(b',')]
        remote = self.environ.get(b'REMOTE_ADDR')
        if remote:
            return [remote]
        return []

    @property
    def remote_addr(self):
        route = self.remote_route
        if route:
            return route[0]
        else:
            return

    def copy(self):
        return Request(self.environ.copy())

    def get(self, value, default=None):
        return self.environ.get(value, default)

    def __getitem__(self, key):
        return self.environ[key]

    def __delitem__(self, key):
        self[key] = b''
        del self.environ[key]
        return

    def __iter__(self):
        return iter(self.environ)

    def __len__(self):
        return len(self.environ)

    def keys(self):
        return self.environ.keys()

    def __setitem__(self, key, value):
        if self.environ.get(b'bottle.request.readonly'):
            raise KeyError(b'The environ dictionary is read-only.')
        self.environ[key] = value
        todelete = ()
        if key == b'wsgi.input':
            todelete = (b'body', b'forms', b'files', b'params', b'post', b'json')
        elif key == b'QUERY_STRING':
            todelete = (b'query', b'params')
        elif key.startswith(b'HTTP_'):
            todelete = (b'headers', b'cookies')
        for key in todelete:
            self.environ.pop(b'bottle.request.' + key, None)

        return

    def __repr__(self):
        return b'<%s: %s %s>' % (self.__class__.__name__, self.method, self.url)

    def __getattr__(self, name):
        try:
            var = self.environ[b'bottle.request.ext.%s' % name]
            if hasattr(var, b'__get__'):
                return var.__get__(self)
            return var
        except KeyError:
            raise AttributeError(b'Attribute %r not defined.' % name)

        return

    def __setattr__(self, name, value):
        if name == b'environ':
            return object.__setattr__(self, name, value)
        self.environ[b'bottle.request.ext.%s' % name] = value
        return


def _hkey(key):
    if b'\n' in key or b'\r' in key or b'\x00' in key:
        raise ValueError(b'Header names must not contain control characters: %r' % key)
    return key.title().replace(b'_', b'-')


def _hval(value):
    value = tonat(value)
    if b'\n' in value or b'\r' in value or b'\x00' in value:
        raise ValueError(b'Header value must not contain control characters: %r' % value)
    return value


class HeaderProperty(object):

    def __init__(self, name, reader=None, writer=None, default=b''):
        self.name, self.default = name, default
        self.reader, self.writer = reader, writer
        self.__doc__ = b'Current value of the %r header.' % name.title()
        return

    def __get__(self, obj, cls):
        if obj is None:
            return self
        else:
            value = obj.get_header(self.name, self.default)
            if self.reader:
                return self.reader(value)
            return value

    def __set__(self, obj, value):
        obj[self.name] = self.writer(value) if self.writer else value
        return

    def __delete__(self, obj):
        del obj[self.name]
        return


class BaseResponse(object):
    default_status = 200
    default_content_type = b'text/html; charset=UTF-8'
    bad_headers = {204: (set((b'Content-Type',))), 
       304: (set((b'Allow', b'Content-Encoding', b'Content-Language', b'Content-Length', b'Content-Range', b'Content-Type', b'Content-Md5', b'Last-Modified')))}

    def __init__(self, body=b'', status=None, headers=None, **more_headers):
        self._cookies = None
        self._headers = {}
        self.body = body
        self.status = status or self.default_status
        if headers:
            if isinstance(headers, dict):
                headers = headers.items()
            for name, value in headers:
                self.add_header(name, value)

        if more_headers:
            for name, value in more_headers.items():
                self.add_header(name, value)

        return

    def copy(self, cls=None):
        cls = cls or BaseResponse
        copy = cls()
        copy.status = self.status
        copy._headers = dict((k, v[:]) for k, v in self._headers.items())
        if self._cookies:
            copy._cookies = SimpleCookie()
            copy._cookies.load(self._cookies.output(header=b''))
        return copy

    def __iter__(self):
        return iter(self.body)

    def close(self):
        if hasattr(self.body, b'close'):
            self.body.close()
        return

    @property
    def status_line(self):
        return self._status_line

    @property
    def status_code(self):
        return self._status_code

    def _set_status(self, status):
        if isinstance(status, int):
            code, status = status, _HTTP_STATUS_LINES.get(status)
        elif b' ' in status:
            status = status.strip()
            code = int(status.split()[0])
        else:
            raise ValueError(b'String status line without a reason phrase.')
        if not 100 <= code <= 999:
            raise ValueError(b'Status code out of range.')
        self._status_code = code
        self._status_line = str(status or b'%d Unknown' % code)
        return

    def _get_status(self):
        return self._status_line

    status = property(_get_status, _set_status, None, b' A writeable property to change the HTTP response status. It accepts\n            either a numeric code (100-999) or a string with a custom reason\n            phrase (e.g. "404 Brain not found"). Both :data:`status_line` and\n            :data:`status_code` are updated accordingly. The return value is\n            always a status string. ')
    del _get_status
    del _set_status

    @property
    def headers(self):
        hdict = HeaderDict()
        hdict.dict = self._headers
        return hdict

    def __contains__(self, name):
        return _hkey(name) in self._headers

    def __delitem__(self, name):
        del self._headers[_hkey(name)]
        return

    def __getitem__(self, name):
        return self._headers[_hkey(name)][-1]

    def __setitem__(self, name, value):
        self._headers[_hkey(name)] = [
         _hval(value)]
        return

    def get_header(self, name, default=None):
        return self._headers.get(_hkey(name), [default])[-1]

    def set_header(self, name, value):
        self._headers[_hkey(name)] = [
         _hval(value)]
        return

    def add_header(self, name, value):
        self._headers.setdefault(_hkey(name), []).append(_hval(value))
        return

    def iter_headers(self):
        return self.headerlist

    @property
    def headerlist(self):
        out = []
        headers = list(self._headers.items())
        if b'Content-Type' not in self._headers:
            headers.append((b'Content-Type', [self.default_content_type]))
        if self._status_code in self.bad_headers:
            bad_headers = self.bad_headers[self._status_code]
            headers = [h for h in headers if h[0] not in bad_headers]
        out += [(name, val) for name, vals in headers for val in vals]
        if self._cookies:
            for c in self._cookies.values():
                out.append((b'Set-Cookie', c.OutputString()))

        return out

    content_type = HeaderProperty(b'Content-Type')
    content_length = HeaderProperty(b'Content-Length', reader=int)
    expires = HeaderProperty(b'Expires', reader=(lambda x: datetime.utcfromtimestamp(parse_date(x))), writer=(lambda x: http_date(x)))

    @property
    def charset(self, default=b'UTF-8'):
        if b'charset=' in self.content_type:
            return self.content_type.split(b'charset=')[-1].split(b';')[0].strip()
        return default

    def set_cookie(self, name, value, secret=None, **options):
        if not self._cookies:
            self._cookies = SimpleCookie()
        if secret:
            value = touni(cookie_encode((name, value), secret))
        elif not isinstance(value, basestring):
            raise TypeError(b'Secret key missing for non-string Cookie.')
        if len(value) > 4096:
            raise ValueError(b'Cookie value to long.')
        self._cookies[name] = value
        for key, value in options.items():
            if key == b'max_age':
                if isinstance(value, timedelta):
                    value = value.seconds + value.days * 24 * 3600
            if key == b'expires':
                if isinstance(value, (datedate, datetime)):
                    value = value.timetuple()
                elif isinstance(value, (int, float)):
                    value = time.gmtime(value)
                value = time.strftime(b'%a, %d %b %Y %H:%M:%S GMT', value)
            self._cookies[name][key.replace(b'_', b'-')] = value

        return

    def delete_cookie(self, key, **kwargs):
        kwargs[b'max_age'] = -1
        kwargs[b'expires'] = 0
        self.set_cookie(key, b'', **kwargs)
        return

    def __repr__(self):
        out = b''
        for name, value in self.headerlist:
            out += b'%s: %s\n' % (name.title(), value.strip())

        return out


def local_property(name=None):
    if name:
        depr(b'local_property() is deprecated and will be removed.')
    ls = threading.local()

    def fget(self):
        try:
            return ls.var
        except AttributeError:
            raise RuntimeError(b'Request context not initialized.')

        return

    def fset(self, value):
        ls.var = value
        return

    def fdel(self):
        del ls.var
        return

    return property(fget, fset, fdel, b'Thread-local property')


class LocalRequest(BaseRequest):
    bind = BaseRequest.__init__
    environ = local_property()


class LocalResponse(BaseResponse):
    bind = BaseResponse.__init__
    _status_line = local_property()
    _status_code = local_property()
    _cookies = local_property()
    _headers = local_property()
    body = local_property()


Request = BaseRequest
Response = BaseResponse

class HTTPResponse(Response, BottleException):

    def __init__(self, body=b'', status=None, headers=None, **more_headers):
        super(HTTPResponse, self).__init__(body, status, headers, **more_headers)
        return

    def apply(self, response):
        response._status_code = self._status_code
        response._status_line = self._status_line
        response._headers = self._headers
        response._cookies = self._cookies
        response.body = self.body
        return


class HTTPError(HTTPResponse):
    default_status = 500

    def __init__(self, status=None, body=None, exception=None, traceback=None, **options):
        self.exception = exception
        self.traceback = traceback
        super(HTTPError, self).__init__(body, status, **options)
        return


class PluginError(BottleException):
    pass


class JSONPlugin(object):
    name = b'json'
    api = 2

    def __init__(self, json_dumps=json_dumps):
        self.json_dumps = json_dumps
        return

    def apply(self, callback, route):
        dumps = self.json_dumps
        if not dumps:
            return callback

        def wrapper(*a, **ka):
            try:
                rv = callback(*a, **ka)
            except HTTPError:
                rv = _e()

            if isinstance(rv, dict):
                json_response = dumps(rv)
                response.content_type = b'application/json'
                return json_response
            if isinstance(rv, HTTPResponse) and isinstance(rv.body, dict):
                rv.body = dumps(rv.body)
                rv.content_type = b'application/json'
            return rv

        return wrapper


class TemplatePlugin(object):
    name = b'template'
    api = 2

    def apply(self, callback, route):
        conf = route.config.get(b'template')
        if isinstance(conf, (tuple, list)) and len(conf) == 2:
            return view(conf[0], **conf[1])(callback)
        else:
            if isinstance(conf, str):
                return view(conf)(callback)
            return callback

        return


class _ImportRedirect(object):

    def __init__(self, name, impmask):
        self.name = name
        self.impmask = impmask
        self.module = sys.modules.setdefault(name, imp.new_module(name))
        self.module.__dict__.update({b'__file__': __file__, b'__path__': [], b'__all__': [], b'__loader__': self})
        sys.meta_path.append(self)
        return

    def find_module(self, fullname, path=None):
        if b'.' not in fullname:
            return
        packname = fullname.rsplit(b'.', 1)[0]
        if packname != self.name:
            return
        return self

    def load_module(self, fullname):
        if fullname in sys.modules:
            return sys.modules[fullname]
        modname = fullname.rsplit(b'.', 1)[1]
        realname = self.impmask % modname
        __import__(realname)
        module = sys.modules[fullname] = sys.modules[realname]
        setattr(self.module, modname, module)
        module.__loader__ = self
        return module


class MultiDict(DictMixin):

    def __init__(self, *a, **k):
        self.dict = dict((k, [v]) for k, v in dict(*a, **k).items())
        return

    def __len__(self):
        return len(self.dict)

    def __iter__(self):
        return iter(self.dict)

    def __contains__(self, key):
        return key in self.dict

    def __delitem__(self, key):
        del self.dict[key]
        return

    def __getitem__(self, key):
        return self.dict[key][-1]

    def __setitem__(self, key, value):
        self.append(key, value)
        return

    def keys(self):
        return self.dict.keys()

    if py3k:

        def values(self):
            return (v[-1] for v in self.dict.values())

        def items(self):
            return ((k, v[-1]) for k, v in self.dict.items())

        def allitems(self):
            return ((k, v) for k, vl in self.dict.items() for v in vl)

        iterkeys = keys
        itervalues = values
        iteritems = items
        iterallitems = allitems
    else:

        def values(self):
            return [v[-1] for v in self.dict.values()]

        def items(self):
            return [(k, v[-1]) for k, v in self.dict.items()]

        def iterkeys(self):
            return self.dict.iterkeys()

        def itervalues(self):
            return (v[-1] for v in self.dict.itervalues())

        def iteritems(self):
            return ((k, v[-1]) for k, v in self.dict.iteritems())

        def iterallitems(self):
            return ((k, v) for k, vl in self.dict.iteritems() for v in vl)

        def allitems(self):
            return [(k, v) for k, vl in self.dict.iteritems() for v in vl]

    def get(self, key, default=None, index=-1, type=None):
        try:
            val = self.dict[key][index]
            if type:
                return type(val)
            return val
        except Exception:
            pass

        return default

    def append(self, key, value):
        self.dict.setdefault(key, []).append(value)
        return

    def replace(self, key, value):
        self.dict[key] = [
         value]
        return

    def getall(self, key):
        return self.dict.get(key) or []

    getone = get
    getlist = getall


class FormsDict(MultiDict):
    input_encoding = b'utf8'
    recode_unicode = True

    def _fix(self, s, encoding=None):
        if isinstance(s, unicode) and self.recode_unicode:
            return s.encode(b'latin1').decode(encoding or self.input_encoding)
        if isinstance(s, bytes):
            return s.decode(encoding or self.input_encoding)
        return s
        return

    def decode(self, encoding=None):
        copy = FormsDict()
        enc = copy.input_encoding = encoding or self.input_encoding
        copy.recode_unicode = False
        for key, value in self.allitems():
            copy.append(self._fix(key, enc), self._fix(value, enc))

        return copy

    def getunicode(self, name, default=None, encoding=None):
        try:
            return self._fix(self[name], encoding)
        except (UnicodeError, KeyError):
            return default

        return

    def __getattr__(self, name, default=unicode()):
        if name.startswith(b'__') and name.endswith(b'__'):
            return super(FormsDict, self).__getattr__(name)
        return self.getunicode(name, default=default)


class HeaderDict(MultiDict):

    def __init__(self, *a, **ka):
        self.dict = {}
        if a or ka:
            self.update(*a, **ka)
        return

    def __contains__(self, key):
        return _hkey(key) in self.dict

    def __delitem__(self, key):
        del self.dict[_hkey(key)]
        return

    def __getitem__(self, key):
        return self.dict[_hkey(key)][-1]

    def __setitem__(self, key, value):
        self.dict[_hkey(key)] = [
         _hval(value)]
        return

    def append(self, key, value):
        self.dict.setdefault(_hkey(key), []).append(_hval(value))
        return

    def replace(self, key, value):
        self.dict[_hkey(key)] = [
         _hval(value)]
        return

    def getall(self, key):
        return self.dict.get(_hkey(key)) or []

    def get(self, key, default=None, index=-1):
        return MultiDict.get(self, _hkey(key), default, index)

    def filter(self, names):
        for name in (_hkey(n) for n in names):
            if name in self.dict:
                del self.dict[name]

        return


class WSGIHeaderDict(DictMixin):
    cgikeys = (b'CONTENT_TYPE', b'CONTENT_LENGTH')

    def __init__(self, environ):
        self.environ = environ
        return

    def _ekey(self, key):
        key = key.replace(b'-', b'_').upper()
        if key in self.cgikeys:
            return key
        return b'HTTP_' + key

    def raw(self, key, default=None):
        return self.environ.get(self._ekey(key), default)

    def __getitem__(self, key):
        return tonat(self.environ[self._ekey(key)], b'latin1')

    def __setitem__(self, key, value):
        raise TypeError(b'%s is read-only.' % self.__class__)
        return

    def __delitem__(self, key):
        raise TypeError(b'%s is read-only.' % self.__class__)
        return

    def __iter__(self):
        for key in self.environ:
            if key[:5] == b'HTTP_':
                yield key[5:].replace(b'_', b'-').title()
            elif key in self.cgikeys:
                yield key.replace(b'_', b'-').title()

        return

    def keys(self):
        return [x for x in self]

    def __len__(self):
        return len(self.keys())

    def __contains__(self, key):
        return self._ekey(key) in self.environ


class ConfigDict(dict):
    __slots__ = (b'_meta', b'_on_change')

    class Namespace(DictMixin):

        def __init__(self, config, namespace):
            self._config = config
            self._prefix = namespace
            return

        def __getitem__(self, key):
            depr(b'Accessing namespaces as dicts is discouraged. Only use flat item access: cfg["names"]["pace"]["key"] -> cfg["name.space.key"]')
            return self._config[self._prefix + b'.' + key]

        def __setitem__(self, key, value):
            self._config[self._prefix + b'.' + key] = value
            return

        def __delitem__(self, key):
            del self._config[self._prefix + b'.' + key]
            return

        def __iter__(self):
            ns_prefix = self._prefix + b'.'
            for key in self._config:
                ns, dot, name = key.rpartition(b'.')
                if ns == self._prefix and name:
                    yield name

            return

        def keys(self):
            return [x for x in self]

        def __len__(self):
            return len(self.keys())

        def __contains__(self, key):
            return self._prefix + b'.' + key in self._config

        def __repr__(self):
            return b'<Config.Namespace %s.*>' % self._prefix

        def __str__(self):
            return b'<Config.Namespace %s.*>' % self._prefix

        def __getattr__(self, key):
            depr(b'Attribute access is deprecated.')
            if key not in self and key[0].isupper():
                self[key] = ConfigDict.Namespace(self._config, self._prefix + b'.' + key)
            if key not in self and key.startswith(b'__'):
                raise AttributeError(key)
            return self.get(key)

        def __setattr__(self, key, value):
            if key in (b'_config', b'_prefix'):
                self.__dict__[key] = value
                return
            depr(b'Attribute assignment is deprecated.')
            if hasattr(DictMixin, key):
                raise AttributeError(b'Read-only attribute.')
            if key in self and self[key] and isinstance(self[key], self.__class__):
                raise AttributeError(b'Non-empty namespace attribute.')
            self[key] = value
            return

        def __delattr__(self, key):
            if key in self:
                val = self.pop(key)
                if isinstance(val, self.__class__):
                    prefix = key + b'.'
                    for key in self:
                        if key.startswith(prefix):
                            del self[prefix + key]

            return

        def __call__(self, *a, **ka):
            depr(b'Calling ConfDict is deprecated. Use the update() method.')
            self.update(*a, **ka)
            return self

    def __init__(self, *a, **ka):
        self._meta = {}
        self._on_change = lambda name, value: None
        if a or ka:
            depr(b'Constructor does no longer accept parameters.')
            self.update(*a, **ka)
        return

    def load_config(self, filename):
        conf = ConfigParser()
        conf.read(filename)
        for section in conf.sections():
            for key, value in conf.items(section):
                if section not in (b'DEFAULT', b'bottle'):
                    key = section + b'.' + key
                self[key] = value

        return self

    def load_dict(self, source, namespace=b'', make_namespaces=False):
        stack = [
         (
          namespace, source)]
        while stack:
            prefix, source = stack.pop()
            if not isinstance(source, dict):
                raise TypeError(b'Source is not a dict (r)' % type(key))
            for key, value in source.items():
                if not isinstance(key, basestring):
                    raise TypeError(b'Key is not a string (%r)' % type(key))
                full_key = prefix + b'.' + key if prefix else key
                if isinstance(value, dict):
                    stack.append((full_key, value))
                    if make_namespaces:
                        self[full_key] = self.Namespace(self, full_key)
                else:
                    self[full_key] = value

        return self

    def update(self, *a, **ka):
        prefix = b''
        if a and isinstance(a[0], basestring):
            prefix = a[0].strip(b'.') + b'.'
            a = a[1:]
        for key, value in dict(*a, **ka).items():
            self[prefix + key] = value

        return

    def setdefault(self, key, value):
        if key not in self:
            self[key] = value
        return self[key]

    def __setitem__(self, key, value):
        if not isinstance(key, basestring):
            raise TypeError(b'Key has type %r (not a string)' % type(key))
        value = self.meta_get(key, b'filter', (lambda x: x))(value)
        if key in self and self[key] is value:
            return
        self._on_change(key, value)
        dict.__setitem__(self, key, value)
        return

    def __delitem__(self, key):
        dict.__delitem__(self, key)
        return

    def clear(self):
        for key in self:
            del self[key]

        return

    def meta_get(self, key, metafield, default=None):
        return self._meta.get(key, {}).get(metafield, default)

    def meta_set(self, key, metafield, value):
        self._meta.setdefault(key, {})[metafield] = value
        if key in self:
            self[key] = self[key]
        return

    def meta_list(self, key):
        return self._meta.get(key, {}).keys()

    def __getattr__(self, key):
        depr(b'Attribute access is deprecated.')
        if key not in self and key[0].isupper():
            self[key] = self.Namespace(self, key)
        if key not in self and key.startswith(b'__'):
            raise AttributeError(key)
        return self.get(key)

    def __setattr__(self, key, value):
        if key in self.__slots__:
            return dict.__setattr__(self, key, value)
        depr(b'Attribute assignment is deprecated.')
        if hasattr(dict, key):
            raise AttributeError(b'Read-only attribute.')
        if key in self and self[key] and isinstance(self[key], self.Namespace):
            raise AttributeError(b'Non-empty namespace attribute.')
        self[key] = value
        return

    def __delattr__(self, key):
        if key in self:
            val = self.pop(key)
            if isinstance(val, self.Namespace):
                prefix = key + b'.'
                for key in self:
                    if key.startswith(prefix):
                        del self[prefix + key]

        return

    def __call__(self, *a, **ka):
        depr(b'Calling ConfDict is deprecated. Use the update() method.')
        self.update(*a, **ka)
        return self


