class WSGIFileWrapper(object):

    def __init__(self, fp, buffer_size=65536):
        self.fp, self.buffer_size = fp, buffer_size
        for attr in (b'fileno', b'close', b'read', b'readlines', b'tell', b'seek'):
            if hasattr(fp, attr):
                setattr(self, attr, getattr(fp, attr))

        return

