class FapwsServer(ServerAdapter):

    def run(self, handler):
        import fapws._evwsgi as evwsgi
        from fapws import base, config
        port = self.port
        if float(config.SERVER_IDENT[-2:]) > 0.4:
            port = str(port)
        evwsgi.start(self.host, port)
        if b'BOTTLE_CHILD' in os.environ and not self.quiet:
            _stderr(b'WARNING: Auto-reloading does not work with Fapws3.\n')
            _stderr(b'         (Fapws3 breaks python thread support)\n')
        evwsgi.set_base_module(base)

        def app(environ, start_response):
            environ[b'wsgi.multiprocess'] = False
            return handler(environ, start_response)

        evwsgi.wsgi_cb((b'', app))
        evwsgi.run()
        return


