def load(target, **namespace):
    module, target = target.split(b':', 1) if b':' in target else (target, None)
    if module not in sys.modules:
        __import__(module)
    if not target:
        return sys.modules[module]
    else:
        if target.isalnum():
            return getattr(sys.modules[module], target)
        package_name = module.split(b'.')[0]
        namespace[package_name] = sys.modules[package_name]
        return eval(b'%s.%s' % (module, target), namespace)


def load_app(target):
    global NORUN
    NORUN, nr_old = True, NORUN
    try:
        tmp = default_app.push()
        rv = load(target)
        if callable(rv):
            return rv
        return tmp
    finally:
        default_app.remove(tmp)
        NORUN = nr_old

    return


_debug = debug

def run(app=None, server=b'wsgiref', host=b'127.0.0.1', port=8080, interval=1, reloader=False, quiet=False, plugins=None, debug=None, **kargs):
    if NORUN:
        return
    else:
        if reloader and not os.environ.get(b'BOTTLE_CHILD'):
            try:
                try:
                    lockfile = None
                    fd, lockfile = tempfile.mkstemp(prefix=b'bottle.', suffix=b'.lock')
                    os.close(fd)
                    while os.path.exists(lockfile):
                        args = [
                         sys.executable] + sys.argv
                        environ = os.environ.copy()
                        environ[b'BOTTLE_CHILD'] = b'true'
                        environ[b'BOTTLE_LOCKFILE'] = lockfile
                        p = subprocess.Popen(args, env=environ)
                        while p.poll() is None:
                            os.utime(lockfile, None)
                            time.sleep(interval)

                        if p.poll() != 3:
                            if os.path.exists(lockfile):
                                os.unlink(lockfile)
                            sys.exit(p.poll())

                except KeyboardInterrupt:
                    pass

            finally:
                if os.path.exists(lockfile):
                    os.unlink(lockfile)

            return
        try:
            if debug is not None:
                _debug(debug)
            app = app or default_app()
            if isinstance(app, basestring):
                app = load_app(app)
            if not callable(app):
                raise ValueError(b'Application is not callable: %r' % app)
            for plugin in plugins or []:
                app.install(plugin)

            if server in server_names:
                server = server_names.get(server)
            if isinstance(server, basestring):
                server = load(server)
            if isinstance(server, type):
                server = server(host=host, port=port, **kargs)
            if not isinstance(server, ServerAdapter):
                raise ValueError(b'Unknown or unsupported server: %r' % server)
            server.quiet = server.quiet or quiet
            if not server.quiet:
                _stderr(b'Bottle v%s server starting up (using %s)...\n' % (__version__, repr(server)))
                _stderr(b'Listening on http://%s:%d/\n' % (server.host, server.port))
                _stderr(b'Hit Ctrl-C to quit.\n\n')
            if reloader:
                lockfile = os.environ.get(b'BOTTLE_LOCKFILE')
                bgcheck = FileCheckerThread(lockfile, interval)
                with bgcheck:
                    server.run(app)
                if bgcheck.status == b'reload':
                    sys.exit(3)
            else:
                server.run(app)
        except KeyboardInterrupt:
            pass
        except (SystemExit, MemoryError):
            raise
        except:
            if not reloader:
                raise
            if not getattr(server, b'quiet', quiet):
                print_exc()
            time.sleep(interval)
            sys.exit(3)

        return


class FileCheckerThread(threading.Thread):

    def __init__(self, lockfile, interval):
        threading.Thread.__init__(self)
        self.lockfile, self.interval = lockfile, interval
        self.status = None
        return

    def run(self):
        exists = os.path.exists
        mtime = lambda path: os.stat(path).st_mtime
        files = dict()
        for module in list(sys.modules.values()):
            path = getattr(module, b'__file__', b'')
            if path[-4:] in (b'.pyo', b'.pyc'):
                path = path[:-1]
            if path and exists(path):
                files[path] = mtime(path)

        while not self.status:
            if not exists(self.lockfile) or mtime(self.lockfile) < time.time() - self.interval - 5:
                self.status = b'error'
                thread.interrupt_main()
            for path, lmtime in list(files.items()):
                if not exists(path) or mtime(path) > lmtime:
                    self.status = b'reload'
                    thread.interrupt_main()
                    break

            time.sleep(self.interval)

        return

    def __enter__(self):
        self.start()
        return

    def __exit__(self, exc_type, exc_val, exc_tb):
        if not self.status:
            self.status = b'exit'
        self.join()
        return exc_type is not None and issubclass(exc_type, KeyboardInterrupt)


class TemplateError(HTTPError):

    def __init__(self, message):
        HTTPError.__init__(self, 500, message)
        return


class BaseTemplate(object):
    extensions = [
     b'tpl', b'html', b'thtml', b'stpl']
    settings = {}
    defaults = {}

    def __init__(self, source=None, name=None, lookup=[], encoding=b'utf8', **settings):
        self.name = name
        self.source = source.read() if hasattr(source, b'read') else source
        self.filename = source.filename if hasattr(source, b'filename') else None
        self.lookup = [os.path.abspath(x) for x in lookup]
        self.encoding = encoding
        self.settings = self.settings.copy()
        self.settings.update(settings)
        if not self.source and self.name:
            self.filename = self.search(self.name, self.lookup)
            if not self.filename:
                raise TemplateError(b'Template %s not found.' % repr(name))
        if not self.source and not self.filename:
            raise TemplateError(b'No template specified.')
        self.prepare(**self.settings)
        return

    @classmethod
    def search(cls, name, lookup=[]):
        if not lookup:
            depr(b'The template lookup path list should not be empty.')
            lookup = [b'.']
        if os.path.isabs(name) and os.path.isfile(name):
            depr(b'Absolute template path names are deprecated.')
            return os.path.abspath(name)
        for spath in lookup:
            spath = os.path.abspath(spath) + os.sep
            fname = os.path.abspath(os.path.join(spath, name))
            if not fname.startswith(spath):
                continue
            if os.path.isfile(fname):
                return fname
            for ext in cls.extensions:
                if os.path.isfile(b'%s.%s' % (fname, ext)):
                    return b'%s.%s' % (fname, ext)

        return

    @classmethod
    def global_config(cls, key, *args):
        if args:
            cls.settings = cls.settings.copy()
            cls.settings[key] = args[0]
        else:
            return cls.settings[key]
        return

    def prepare(self, **options):
        raise NotImplementedError
        return

    def render(self, *args, **kwargs):
        raise NotImplementedError
        return


class MakoTemplate(BaseTemplate):

    def prepare(self, **options):
        from mako.template import Template
        from mako.lookup import TemplateLookup
        options.update({b'input_encoding': (self.encoding)})
        options.setdefault(b'format_exceptions', bool(DEBUG))
        lookup = TemplateLookup(directories=self.lookup, **options)
        if self.source:
            self.tpl = Template(self.source, lookup=lookup, **options)
        else:
            self.tpl = Template(uri=self.name, filename=self.filename, lookup=lookup, **options)
        return

    def render(self, *args, **kwargs):
        for dictarg in args:
            kwargs.update(dictarg)

        _defaults = self.defaults.copy()
        _defaults.update(kwargs)
        return self.tpl.render(**_defaults)


class CheetahTemplate(BaseTemplate):

    def prepare(self, **options):
        from Cheetah.Template import Template
        self.context = threading.local()
        self.context.vars = {}
        options[b'searchList'] = [self.context.vars]
        if self.source:
            self.tpl = Template(source=self.source, **options)
        else:
            self.tpl = Template(file=self.filename, **options)
        return

    def render(self, *args, **kwargs):
        for dictarg in args:
            kwargs.update(dictarg)

        self.context.vars.update(self.defaults)
        self.context.vars.update(kwargs)
        out = str(self.tpl)
        self.context.vars.clear()
        return out


class Jinja2Template(BaseTemplate):

    def prepare(self, filters=None, tests=None, globals={}, **kwargs):
        from jinja2 import Environment, FunctionLoader
        if b'prefix' in kwargs:
            raise RuntimeError(b'The keyword argument `prefix` has been removed. Use the full jinja2 environment name line_statement_prefix instead.')
        self.env = Environment(loader=FunctionLoader(self.loader), **kwargs)
        if filters:
            self.env.filters.update(filters)
        if tests:
            self.env.tests.update(tests)
        if globals:
            self.env.globals.update(globals)
        if self.source:
            self.tpl = self.env.from_string(self.source)
        else:
            self.tpl = self.env.get_template(self.filename)
        return

    def render(self, *args, **kwargs):
        for dictarg in args:
            kwargs.update(dictarg)

        _defaults = self.defaults.copy()
        _defaults.update(kwargs)
        return self.tpl.render(**_defaults)

    def loader(self, name):
        fname = self.search(name, self.lookup)
        if not fname:
            return
        with open(fname, b'rb') as f:
            return f.read().decode(self.encoding)
        return


class SimpleTemplate(BaseTemplate):

    def prepare(self, escape_func=html_escape, noescape=False, syntax=None, **ka):
        self.cache = {}
        enc = self.encoding
        self._str = lambda x: touni(x, enc)
        self._escape = lambda x: escape_func(touni(x, enc))
        self.syntax = syntax
        if noescape:
            self._str, self._escape = self._escape, self._str
        return

    @cached_property
    def co(self):
        return compile(self.code, self.filename or b'<string>', b'exec')

    @cached_property
    def code(self):
        source = self.source
        if not source:
            with open(self.filename, b'rb') as f:
                source = f.read()
        try:
            source, encoding = touni(source), b'utf8'
        except UnicodeError:
            depr(b'Template encodings other than utf8 are no longer supported.')
            source, encoding = touni(source, b'latin1'), b'latin1'

        parser = StplParser(source, encoding=encoding, syntax=self.syntax)
        code = parser.translate()
        self.encoding = parser.encoding
        return code

    def _rebase(self, _env, _name=None, **kwargs):
        if _name is None:
            depr(b'Rebase function called without arguments. You were probably looking for {{base}}?', True)
        _env[b'_rebase'] = (
         _name, kwargs)
        return

    def _include(self, _env, _name=None, **kwargs):
        if _name is None:
            depr(b'Rebase function called without arguments. You were probably looking for {{base}}?', True)
        env = _env.copy()
        env.update(kwargs)
        if _name not in self.cache:
            self.cache[_name] = self.__class__(name=_name, lookup=self.lookup)
        return self.cache[_name].execute(env[b'_stdout'], env)

    def execute(self, _stdout, kwargs):
        env = self.defaults.copy()
        env.update(kwargs)
        env.update({b'_stdout': _stdout, b'_printlist': (_stdout.extend), b'include': (functools.partial(self._include, env)), 
           b'rebase': (functools.partial(self._rebase, env)), 
           b'_rebase': None, b'_str': (self._str), 
           b'_escape': (self._escape), b'get': (env.get), b'setdefault': (env.setdefault), 
           b'defined': (env.__contains__)})
        eval(self.co, env)
        if env.get(b'_rebase'):
            subtpl, rargs = env.pop(b'_rebase')
            rargs[b'base'] = (b'').join(_stdout)
            del _stdout[:]
            return self._include(env, subtpl, **rargs)
        else:
            return env

    def render(self, *args, **kwargs):
        env = {}
        stdout = []
        for dictarg in args:
            env.update(dictarg)

        env.update(kwargs)
        self.execute(stdout, env)
        return (b'').join(stdout)


class StplSyntaxError(TemplateError):
    pass


class StplParser(object):
    _re_cache = {}
    _re_tok = b'((?m)[urbURB]?(?:\'\'(?!\')|""(?!")|\'{6}|"{6}|\'(?:[^\\\\\']|\\\\.)+?\'|"(?:[^\\\\"]|\\\\.)+?"|\'{3}(?:[^\\\\]|\\\\.|\\n)+?\'{3}|"{3}(?:[^\\\\]|\\\\.|\\n)+?"{3}))'
    _re_inl = _re_tok.replace(b'|\\n', b'')
    _re_tok += b'|(#.*)'
    _re_tok += b'|([\\[\\{\\(])'
    _re_tok += b'|([\\]\\}\\)])'
    _re_tok += b'|^([ \\t]*(?:if|for|while|with|try|def|class)\\b)|^([ \\t]*(?:elif|else|except|finally)\\b)'
    _re_tok += b'|((?:^|;)[ \\t]*end[ \\t]*(?=(?:%(block_close)s[ \\t]*)?\\r?$|;|#))'
    _re_tok += b'|(%(block_close)s[ \\t]*(?=\\r?$))'
    _re_tok += b'|(\\r?\\n)'
    _re_split = b'(?m)^[ \t]*(\\\\?)((%(line_start)s)|(%(block_start)s))(%%?)'
    _re_inl = b'%%(inline_start)s((?:%s|[^\'"\n]*?)+)%%(inline_end)s' % _re_inl
    default_syntax = b'<% %> % {{ }}'

    def __init__(self, source, syntax=None, encoding=b'utf8'):
        self.source, self.encoding = touni(source, encoding), encoding
        self.set_syntax(syntax or self.default_syntax)
        self.code_buffer, self.text_buffer = [], []
        self.lineno, self.offset = (1, 0)
        self.indent, self.indent_mod = (0, 0)
        self.paren_depth = 0
        return

    def get_syntax(self):
        return self._syntax

    def set_syntax(self, syntax):
        self._syntax = syntax
        self._tokens = syntax.split()
        if syntax not in self._re_cache:
            names = b'block_start block_close line_start inline_start inline_end'
            etokens = map(re.escape, self._tokens)
            pattern_vars = dict(zip(names.split(), etokens))
            patterns = (self._re_split, self._re_tok, self._re_inl)
            patterns = [re.compile(p % pattern_vars) for p in patterns]
            self._re_cache[syntax] = patterns
        self.re_split, self.re_tok, self.re_inl = self._re_cache[syntax]
        return

    syntax = property(get_syntax, set_syntax)

    def translate(self):
        if self.offset:
            raise RuntimeError(b'Parser is a one time instance.')
        while True:
            m = self.re_split.search(self.source[self.offset:])
            if m:
                text = self.source[self.offset:self.offset + m.start()]
                self.text_buffer.append(text)
                self.offset += m.end()
                if m.group(1):
                    line, sep, _ = self.source[self.offset:].partition(b'\n')
                    self.text_buffer.append(m.group(2) + m.group(5) + line + sep)
                    self.offset += len(line + sep) + 1
                    continue
                elif m.group(5):
                    depr(b'Escape code lines with a backslash.')
                    line, sep, _ = self.source[self.offset:].partition(b'\n')
                    self.text_buffer.append(m.group(2) + line + sep)
                    self.offset += len(line + sep) + 1
                    continue
                self.flush_text()
                self.read_code(multiline=bool(m.group(4)))
            else:
                break

        self.text_buffer.append(self.source[self.offset:])
        self.flush_text()
        return (b'').join(self.code_buffer)

    def read_code(self, multiline):
        code_line, comment = (b'', b'')
        while True:
            m = self.re_tok.search(self.source[self.offset:])
            if not m:
                code_line += self.source[self.offset:]
                self.offset = len(self.source)
                self.write_code(code_line.strip(), comment)
                return
            code_line += self.source[self.offset:self.offset + m.start()]
            self.offset += m.end()
            _str, _com, _po, _pc, _blk1, _blk2, _end, _cend, _nl = m.groups()
            if (code_line or self.paren_depth > 0) and (_blk1 or _blk2):
                code_line += _blk1 or _blk2
                continue
            if _str:
                code_line += _str
            elif _com:
                comment = _com
                if multiline and _com.strip().endswith(self._tokens[1]):
                    multiline = False
            elif _po:
                self.paren_depth += 1
                code_line += _po
            elif _pc:
                if self.paren_depth > 0:
                    self.paren_depth -= 1
                code_line += _pc
            elif _blk1:
                code_line, self.indent_mod = _blk1, -1
                self.indent += 1
            elif _blk2:
                code_line, self.indent_mod = _blk2, -1
            elif _end:
                self.indent -= 1
            elif _cend:
                if multiline:
                    multiline = False
                else:
                    code_line += _cend
            else:
                self.write_code(code_line.strip(), comment)
                self.lineno += 1
                code_line, comment, self.indent_mod = (b'', b'', 0)
                if not multiline:
                    break

        return

    def flush_text(self):
        text = (b'').join(self.text_buffer)
        del self.text_buffer[:]
        if not text:
            return
        parts, pos, nl = [], 0, b'\\\n' + b'  ' * self.indent
        for m in self.re_inl.finditer(text):
            prefix, pos = text[pos:m.start()], m.end()
            if prefix:
                parts.append(nl.join(map(repr, prefix.splitlines(True))))
            if prefix.endswith(b'\n'):
                parts[-1] += nl
            parts.append(self.process_inline(m.group(1).strip()))

        if pos < len(text):
            prefix = text[pos:]
            lines = prefix.splitlines(True)
            if lines[-1].endswith(b'\\\\\n'):
                lines[-1] = lines[-1][:-3]
            elif lines[-1].endswith(b'\\\\\r\n'):
                lines[-1] = lines[-1][:-4]
            parts.append(nl.join(map(repr, lines)))
        code = b'_printlist((%s,))' % (b', ').join(parts)
        self.lineno += code.count(b'\n') + 1
        self.write_code(code)
        return

    def process_inline(self, chunk):
        if chunk[0] == b'!':
            return b'_str(%s)' % chunk[1:]
        return b'_escape(%s)' % chunk

    def write_code(self, line, comment=b''):
        line, comment = self.fix_backward_compatibility(line, comment)
        code = b'  ' * (self.indent + self.indent_mod)
        code += line.lstrip() + comment + b'\n'
        self.code_buffer.append(code)
        return

    def fix_backward_compatibility(self, line, comment):
        parts = line.strip().split(None, 2)
        if parts and parts[0] in (b'include', b'rebase'):
            depr(b'The include and rebase keywords are functions now.')
            if len(parts) == 1:
                return (b'_printlist([base])', comment)
            if len(parts) == 2:
                return (b'_=%s(%r)' % tuple(parts), comment)
            return (
             b'_=%s(%r, %s)' % tuple(parts), comment)
        if self.lineno <= 2 and not line.strip() and b'coding' in comment:
            m = re.match(b'#.*coding[:=]\\s*([-\\w.]+)', comment)
            if m:
                depr(b'PEP263 encoding strings in templates are deprecated.')
                enc = m.group(1)
                self.source = self.source.encode(self.encoding).decode(enc)
                self.encoding = enc
                return (
                 line, comment.replace(b'coding', b'coding*'))
        return (
         line, comment)


def template(*args, **kwargs):
    tpl = args[0] if args else None
    adapter = kwargs.pop(b'template_adapter', SimpleTemplate)
    lookup = kwargs.pop(b'template_lookup', TEMPLATE_PATH)
    tplid = (id(lookup), tpl)
    if tplid not in TEMPLATES or DEBUG:
        settings = kwargs.pop(b'template_settings', {})
        if isinstance(tpl, adapter):
            TEMPLATES[tplid] = tpl
            if settings:
                TEMPLATES[tplid].prepare(**settings)
        elif b'\n' in tpl or b'{' in tpl or b'%' in tpl or b'$' in tpl:
            TEMPLATES[tplid] = adapter(source=tpl, lookup=lookup, **settings)
        else:
            TEMPLATES[tplid] = adapter(name=tpl, lookup=lookup, **settings)
    if not TEMPLATES[tplid]:
        abort(500, b'Template (%s) not found' % tpl)
    for dictarg in args[1:]:
        kwargs.update(dictarg)

    return TEMPLATES[tplid].render(kwargs)


mako_template = functools.partial(template, template_adapter=MakoTemplate)
cheetah_template = functools.partial(template, template_adapter=CheetahTemplate)
jinja2_template = functools.partial(template, template_adapter=Jinja2Template)

def view(tpl_name, **defaults):

    def decorator(func):

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            if isinstance(result, (dict, DictMixin)):
                tplvars = defaults.copy()
                tplvars.update(result)
                return template(tpl_name, **tplvars)
            else:
                if result is None:
                    return template(tpl_name, defaults)
                return result

        return wrapper

    return decorator


mako_view = functools.partial(view, template_adapter=MakoTemplate)
cheetah_view = functools.partial(view, template_adapter=CheetahTemplate)
jinja2_view = functools.partial(view, template_adapter=Jinja2Template)
